from pathlib import Path
import json,hashlib
R=Path(__file__).resolve().parent;P=R.parent;G=P/'ground-material';D=P/'decay-material';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
t=(G/'GroundNumericProbe.java').read_text('utf-8').replace('GroundNumeric','ResurrectionNumeric').replace('GroundMaterialProbe','ResurrectionMaterialProbe').replace('BattleSpellCatalog.groundSpell','BattleSpellCatalog.resurrectionSpell')
