t=t.replace('String result="{\\"cases\\":"+cases+', 'String result="{\\"signed_mp_bound_gaps\\":"+numericGaps+",\\"source_predicted_overflows\\":"+expectedOverflows+",\\"cases\\":"+cases+')
(R/'ResurrectionNumericProbe.java').write_text(t,encoding='utf-8')
t=(D/'test.py').read_text('utf-8').replace("D=R/'build/tests'","D=R/'build/numeric'").replace('DecayPotionMaterialProbe','ResurrectionNumericProbe')
t=t.replace("[R/'ResurrectionNumericProbe.java',Path(__file__)]","[R/'ResurrectionNumericProbe.java',R/'ResurrectionMaterialProbe.java',Path(__file__)]")
t=t.replace("classes,R/'ResurrectionNumericProbe.java')","classes,R/'ResurrectionNumericProbe.java',R/'ResurrectionMaterialProbe.java')")
t=t.replace("v[mode]['cases']==96","v[mode]['cases']==48").replace("['Source_window_bypasses']","['signed_mp_bound_gaps']").replace("['locked_writes']","['locked_write_calls']")
t=t.replace("(8 if mode=='before' else 0)","(v[mode]['source_predicted_overflows'] if mode=='before' else 0)")
