(R/'numeric-adaptation.json').write_text(json.dumps(dict(inputs=[dict(path=str(p),sha256=sha(p))for p in[G/'GroundNumericProbe.java',D/'test.py',Path(__file__)]],scope='48 before/after cases; zero/one/65535 configured MP in isolated snapshots; memory only; original unbounded signed-cost behavior observed separately from corrected bounds'),indent=2),encoding='utf-8')
